import{_ as e,o as r,c as t,a2 as n}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"供应商配置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/providers.md","filePath":"zh/guide/providers.md","lastUpdated":1793458229000}'),s={name:"zh/guide/providers.md"};function a(l,o,i,g,c,d){return r(),t("div",null,[...o[0]||(o[0]=[n('<h1 id="供应商配置" tabindex="-1">供应商配置 <a class="header-anchor" href="#供应商配置" aria-label="Permalink to &quot;供应商配置&quot;">​</a></h1><p>本页逐一介绍支持的供应商：在哪里获取密钥、填在哪里、如何验证，以及最常见的错误。</p><p>所有密钥只保存在 Windows 凭据管理器中名为 <code>MeetCue</code> 的条目里，不会写入配置文件或日志；界面只知道某个密钥“已配置”还是“未配置”。</p><p>在 <strong>设置 › 供应商与费用 › 供应商与模型</strong> 中为每项任务选择供应商并填写模型名。MeetCue 不列出模型和价格：保存密钥后，供应商返回的模型名会作为输入建议，每个供应商旁都有 <strong>查看官网价格</strong> 链接指向其官方价格页。</p><h2 id="soniox" tabindex="-1">Soniox <a class="header-anchor" href="#soniox" aria-label="Permalink to &quot;Soniox&quot;">​</a></h2><p>语音识别，能很好地处理一句话里中英混说，自带句末检测。按音频小时计费。</p><ol><li><strong>获取密钥</strong>：登录 Soniox 控制台，创建一个 API 密钥。</li><li><strong>填写</strong>：<strong>设置 › 供应商与费用 › 接口地址与密钥 › Soniox 密钥</strong>，然后点 <strong>保存并验证</strong>。</li><li><strong>验证</strong>：验证成功后会列出你的账号可用的实时识别模型。</li><li><strong>端点</strong>：Soniox 提供多个端点。保持 <strong>自动</strong>，运行<a href="/meetcue/zh/guide/latency">延迟探测</a>选出最快的一个。</li></ol><p>常见错误：<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>（密钥被拒绝）、<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-002">MC-ASR-002</a>（无法连接）。</p><h2 id="deepgram" tabindex="-1">Deepgram <a class="header-anchor" href="#deepgram" aria-label="Permalink to &quot;Deepgram&quot;">​</a></h2><p>流式语音识别，按音频分钟计费。</p><ol><li><strong>获取密钥</strong>：登录 Deepgram 控制台，打开你的项目，创建一个具有成员权限的 API 密钥。</li><li><strong>填写</strong>：<strong>设置 › 供应商与费用 › 接口地址与密钥 › Deepgram 密钥</strong>，然后点 <strong>保存并验证</strong>。</li><li><strong>验证</strong>：验证成功后会列出你的项目和可用的识别模型。</li><li><strong>语言</strong>：在 <strong>设置 › 音频 › 会议语言</strong> 中设置，主要语言放在前面。Deepgram 无法在同一路音频中同时识别中文和英文，两者都选时只识别主要语言；中英混说的会议更适合用 Soniox。</li></ol><p>常见错误：<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>、<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-003">MC-ASR-003</a>（请求被限流）。</p><h2 id="alibaba-cloud" tabindex="-1">阿里云（Fun-ASR） <a class="header-anchor" href="#alibaba-cloud" aria-label="Permalink to &quot;阿里云（Fun-ASR） {#alibaba-cloud}&quot;">​</a></h2><p>阿里云百炼（Model Studio）的实时语音识别，针对普通话设计，能识别夹杂的英文术语和多种方言。按音频秒数计费。</p><ol><li><strong>获取密钥</strong>：在百炼控制台顶部选择地域（中国大陆以外选新加坡，大陆以内选北京），再在该地域创建 API Key。密钥只能在创建它的地域使用。</li><li><strong>填写</strong>：<strong>设置 › 供应商与费用 › 接口地址与密钥 › Alibaba Cloud (Fun-ASR) 密钥</strong>，然后点 <strong>保存并验证</strong>。</li><li><strong>验证</strong>：验证会开始并结束一个空的识别任务，不消耗音频。</li><li><strong>接口地址</strong>：MeetCue 内置两个地域的地址。如果所选地址拒绝密钥，会自动尝试另一个地域，并继续使用可用的那个。</li><li><strong>模型</strong>：<code>fun-asr-realtime</code>（默认）会把热词作为上下文使用。<code>paraformer-realtime-v2</code> 只在北京地域提供。</li></ol><p>常见错误：<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>（两个地域都拒绝密钥）、<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-003">MC-ASR-003</a>（请求被限流或账户欠费）。</p><h2 id="tencent-cloud" tabindex="-1">腾讯云语音识别 <a class="header-anchor" href="#tencent-cloud" aria-label="Permalink to &quot;腾讯云语音识别 {#tencent-cloud}&quot;">​</a></h2><p>腾讯云的实时语音识别，支持普通话、英语、粤语和多种方言。按音频时长计费。</p><ol><li><strong>获取密钥</strong>：在腾讯云控制台开通语音识别，然后打开 <strong>访问管理 › API 密钥管理</strong>。需要 <strong>AppID</strong>（在同一页面和账号信息中可以看到）、<strong>SecretId</strong> 和对应的 <strong>SecretKey</strong>。</li><li><strong>填写</strong>：在 <strong>设置 › 供应商与费用 › 接口地址与密钥 › Tencent Cloud ASR 密钥</strong> 中，按 <code>AppID:SecretId:SecretKey</code> 的格式一次粘贴三项，然后点 <strong>保存并验证</strong>。</li><li><strong>验证</strong>：验证会建立一个签名连接，不发送音频就关闭。</li><li><strong>模型</strong>：<code>16k_zh_en</code>（默认）能识别同一句中的中英文以及 31 种方言。<code>16k_zh</code> 是更便宜的普通话标准版，<code>16k_yue</code> 为粤语，<code>16k_en</code> 为英语。</li><li><strong>在中国大陆以外使用</strong>：中国站账号在境外可能被拒绝。MeetCue 会以密钥错误的形式显示腾讯云的提示，此时请改用国际站账号。</li></ol><p>常见错误：<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>（签名被拒绝、未开通服务或境外访问）、<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-003">MC-ASR-003</a>（资源包用完、欠费或并发超限）。</p><h2 id="anthropic" tabindex="-1">Anthropic <a class="header-anchor" href="#anthropic" aria-label="Permalink to &quot;Anthropic&quot;">​</a></h2><p>用 Claude 模型做问题检测和要点生成。</p><ol><li><strong>获取密钥</strong>：登录 Claude Console，打开 <strong>API keys</strong> 并创建密钥。为组织充值或添加付款方式。</li><li><strong>填写</strong>：<strong>设置 › 供应商与费用 › 接口地址与密钥 › Anthropic 密钥</strong>，然后点 <strong>保存并验证</strong>。</li><li><strong>验证</strong>：验证时从接口加载模型列表，其中的模型名会作为 <strong>模型</strong> 输入框的建议。也可以填写其他任意模型名。</li><li><strong>接口地址</strong>（可选）：留空则使用 <code>https://api.anthropic.com</code>。如需经由兼容 Messages API 的网关或代理，填写其地址，例如 <code>https://gateway.example.com</code>（缺少 <code>/v1</code> 时 MeetCue 会自动补上）。</li></ol><p>常见错误：<a href="/meetcue/zh/troubleshooting/error-codes#mc-llm-002">MC-LLM-002</a>（密钥被拒绝）、<a href="/meetcue/zh/troubleshooting/error-codes#mc-llm-003">MC-LLM-003</a>（请求被限流）、<a href="/meetcue/zh/troubleshooting/error-codes#mc-llm-004">MC-LLM-004</a>（模型不可用）。</p><h2 id="openai-compatible-apis" tabindex="-1">OpenAI 兼容接口 <a class="header-anchor" href="#openai-compatible-apis" aria-label="Permalink to &quot;OpenAI 兼容接口 {#openai-compatible-apis}&quot;">​</a></h2><p>任何实现了 OpenAI Chat Completions 流式接口的服务，包括自建的模型服务。</p><ol><li><strong>接口地址</strong>：为任务选择 <strong>OpenAI-compatible</strong>，然后在 <strong>设置 › 供应商与费用 › 接口地址与密钥</strong> 中填写以 <code>/v1</code> 结尾的地址，例如 <code>https://llm.example.com/v1</code>。</li><li><strong>密钥</strong>：在 <strong>OpenAI-compatible 密钥</strong> 处粘贴该服务的 API 密钥。不需要密钥的服务可以留空。</li><li><strong>验证</strong>：<strong>保存并验证</strong> 会加载 <code>/v1/models</code>，其中的模型名会作为 <strong>模型</strong> 输入框的建议。请填写你所用服务的模型名。</li><li><strong>价格</strong>：如需费用估算和预算，请在 <strong>设置 › 供应商与费用 › 预算 › 你填写的价格</strong> 中填写该服务的价格。</li></ol><p>部分服务在流式输出时不返回 token 用量，此时其用量和费用显示为零。</p><h2 id="corporate-networks" tabindex="-1">公司网络 <a class="header-anchor" href="#corporate-networks" aria-label="Permalink to &quot;公司网络 {#corporate-networks}&quot;">​</a></h2><p>MeetCue 使用 Windows 证书库，公司安装的证书会被信任。所有连接（包括语音识别）都跟随 Windows 设置中手动配置的代理（<strong>网络和 Internet › 代理</strong>）。MeetCue 不会执行自动配置脚本；如果你的网络使用自动配置脚本，或要使用其他代理，请在 <strong>设置 › 供应商与费用 › 高级 › HTTPS 代理</strong> 中填写。如果连接失败并显示 <a href="/meetcue/zh/troubleshooting/error-codes#mc-net-001">MC-NET-001</a>，请看<a href="/meetcue/zh/troubleshooting/latency#company-network">延迟偏高</a>。</p>',30)])])}const u=e(s,[["render",a]]);export{p as __pageData,u as default};
